    text = open(name).read()
    if args[0] == "check" and "BADX" in text:
        bad.append(name + ":1:1: X100 bad thing here")
    if args[0] == "format" and "UNFORMATTED" in text:
        bad.append("Would reformat: " + name)
print("\n".join(bad))
